struct memento {                /* defined only in this .c file */
    int cursor;
    size_t len;
    char *text;                 /* deep copy of the payload */
};

struct memento *editor_save(const struct editor *e) {
    struct memento *m = malloc(sizeof *m);
    m->cursor = e->cursor; m->len = e->len;
    m->text = malloc(e->len + 1);
    memcpy(m->text, e->text, e->len + 1);   /* ranges must not overlap */
    return m;                               /* callers get an opaque pointer */
}
